const A='123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';
function enc(buf){
  let n=0n; for(const b of buf) n=n*256n+BigInt(b);
  let s=''; if(n===0n&&buf.length===0) return '';
  while(n>0n){ s=A[Number(n%58n)]+s; n/=58n; }
  let z=0; while(z<buf.length&&buf[z]===0) z++;
  return '1'.repeat(z)+s;
}
const mode=process.argv[2];
if(mode==='all'){ // all 256 bytes
  const b=Buffer.alloc(256); for(let i=0;i<256;i++) b[i]=i;
  console.log(enc(b));
} else if(mode==='range'){
  const lo=parseInt(process.argv[3]),hi=parseInt(process.argv[4]);
  const b=Buffer.alloc(hi-lo+1); for(let i=lo;i<=hi;i++) b[i-lo]=i;
  console.log(enc(b));
} else if(mode==='hex'){
  console.log(enc(Buffer.from(process.argv[3],'hex')));
}
EOF
